1	/**
2	 * Rainbow water system (water-fx-specialist + foam-bubbles-particles).
3	 *
4	 *   const water = createWater(course, { quality: 'high' });
5	 *   scene.add(water.group);
6	 *   // per frame:
7	 *   water.update(time, dt, bennyS, camera);
8	 *   water.wake(bennyBodyCentre, forward, right, speed, dt);   // centre of the (lifted) body, not the root
9	 *   // cinematic controls (0..1): water.controls.drumSwirl / drumAgitation / outro
10	 *
11	 * Benny rides ON the water: place his body centre at
12	 *   course.pointAt(s, lateral, water.surfaceHeight(s, lateral, time) + BENNY_RIDE_OFFSET)
13	 * (BENNY_RIDE_OFFSET ≈ 0.55 for a 0.8-radius body: bottom third in the water, splash visible).
14	 */
15	import * as THREE from 'three';
16	import { type Course, WORLD, funnelY } from '../world/course';
17	import { createRibbon } from './waterRibbon';
18	import { createWhirlpool, whirlpoolHeight, FUNNEL_LIFT } from './whirlpool';
19	import { createDrumWater } from './drumWater';
20	import { createFinalWave } from './finalWave';
21	import { createPuddles } from './puddles';
22	import { createFoam } from './foam';
23	import { createBubbles } from './bubbles';
24	import { createSpray } from './spray';
25	import { createRiderSplash } from './riderSplash';
26	
27	export { PALETTE } from './glsl';
28	export const BENNY_RIDE_OFFSET = 0.55;
29	/** Benny's outer (fur) radius near the waterline: skin 0.7 + fur 0.12 + lower-body bulge (benny/build.ts BENNY_DIMS) */
30	const BENNY_OUTER_R = 0.86;
31	
32	export interface WaterControls {
33	  /** 02 tumble: spinning water shell on the Drum A wall (0..1) */
34	  drumSwirl: number;
35	  /** Drum A swell size: 0 calm (01) .. 1 spin cycle (02) */
36	  drumAgitation: number;
37	  /** 11 outro: stream drains away (0..1) and leftover puddles appear */
38	  outro: number;
39	}
40	
41	export interface WaterSystem {
42	  group: THREE.Group;
43	  /** call every frame; focusS = Benny's arc-length (for pooling/LOD of bubbles & foam) */
44	  update(time: number, dt: number, focusS: number, camera: THREE.Camera): void;
45	  /** height of the animated water surface above the course centreline frame at (s, lateral) */
46	  surfaceHeight(s: number, lateral: number, time: number): number;
47	  /** spray/wake at Benny: call each frame while riding */
48	  wake(pos: THREE.Vector3, forward: THREE.Vector3, right: THREE.Vector3, speed: number, dt: number): void;
49	  splash(pos: THREE.Vector3, up: THREE.Vector3, strength: number): void;
50	  /** cinematic controls */
51	  controls: WaterControls;
52	  /** sub-systems (for visibility overrides / debugging) */
53	  parts: Record<string, THREE.Object3D>;
54	  /** live stats for perf reporting */
55	  stats(): { instances: number; bubbles: number; smallBubbles: number; sprayCapacity: number };
56	}
57	
58	const smooth = (a: number, b: number, x: number) => {
59	  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
60	  return t * t * (3 - 2 * t);
61	};
62	
63	export function createWater(course: Course, opts: { quality?: 'high' | 'low' } = {}): WaterSystem {
64	  const quality = opts.quality ?? 'high';
65	  const group = new THREE.Group();
66	  group.name = 'water_system';
67	
68	  const drainMark = course.marks['02_drain'] ?? course.stage('02').s1 - 2;
69	  const st03 = course.stage('03'), st04 = course.stage('04'), st08 = course.stage('08'), st09 = course.stage('09');
70	  const ribbonS0 = drainMark - 1;
71	  const ribbon = createRibbon(course, { s0: ribbonS0, s1: course.length, quality });
72	  // open the funnel where the 04 slide tube leaves the basin (the course exits the spiral at
73	  // r≈2.8, just outside the drain hole, and the slide then runs beneath the funnel surface)
74	  const cutPts: THREE.Vector3[] = [];
75	  for (let i = 0; i < 8; i++) {
76	    const s = st04.s0 - 3 + (i / 7) * 34;
77	    const f = course.sample(s);
78	    cutPts.push(f.pos.clone().addScaledVector(f.up, 1.2));
79	  }
80	  const whirl = createWhirlpool(quality, { points: cutPts, radius: Math.max(3.6, course.stage('04').tube * 0.85) });
81	  const drum = createDrumWater(quality);
82	  const wave = createFinalWave(course, quality);
83	  const puddles = createPuddles();
84	  const foam = createFoam(course, { s0: ribbonS0, s1: course.length, quality });
85	  const bubbles = createBubbles(course, { quality, sStart: ribbonS0 });
86	  const spray = createSpray(quality);
87	  const crown = createRiderSplash(quality);
88	  group.add(ribbon.mesh, whirl.mesh, drum.group, wave.mesh, puddles.group, foam.group, bubbles.group, spray.points, crown.mesh);
89	
90	  const parts: Record<string, THREE.Object3D> = { ribbon: ribbon.mesh, whirlpool: whirl.mesh, drum: drum.group, drumSwirl: drum.swirl, finalWave: wave.mesh, puddles: puddles.group, foam: foam.group, foamBerm: foam.berm, bubbles: bubbles.group, bubblesSmall: bubbles.small, bubblesBig: bubbles.big, spray: spray.points, splashCrown: crown.mesh };
91	  const controls: WaterControls = { drumSwirl: 0, drumAgitation: 0, outro: 0 };
92	  // QA: ?waterhide=crown,spray,bubbles,foam,foamBerm,ribbon … hides water parts (isolation captures)
93	  const qaHide = typeof location !== 'undefined' ? (new URLSearchParams(location.search).get('waterhide') ?? '').split(',').filter(Boolean) : [];
94	  /** `waterhide=ribbonWake`: keep the ribbon but switch off its Benny contact/wake block */
95	  const qaNoRibbonWake = qaHide.includes('ribbonWake');
96	  let focus = 0;
97	  let curTime = 0;
98	  const tmpV = new THREE.Vector3();
99	  const tmpV2 = new THREE.Vector3();
100	  const tmpV3 = new THREE.Vector3();
101	  // spray fan scratch (no per-frame allocation)
102	  const sprP = new THREE.Vector3();
103	  const sprV = new THREE.Vector3();
104	  const back = new THREE.Vector3();
105	  const lastWake = new THREE.Vector3();
106	  const riderVel = new THREE.Vector3();
107	  let lastWakeT = -1;
108	  const rnd = (a: number, b: number) => a + Math.random() * (b - a);
109	
110	  /** 0 = ribbon fully shown, 1 = whirlpool surface takes over (mirrors the ribbon vertex shader) */
111	  const whirlBlend = (s: number) => smooth(st03.s0 + 0.5, st03.s0 + 3.5, s) * (1 - smooth(st04.s0 - 9, st04.s0 - 1.5, s));
112	
113	  const surfaceHeight = (s: number, lateral: number, t: number): number => {
114	    if (s < ribbonS0) {
115	      // Drum A: absolute swell height relative to the course point
116	      const p = course.pointAt(s, lateral, 0, tmpV);
117	      const up = course.sample(s).up;
118	      return (drum.heightAt(p.x, p.z, t) - p.y) / Math.max(0.3, up.y);
119	    }
120	    const hr = ribbon.heightAt(s, lateral, t);
121	    const k = whirlBlend(s);
122	    if (k <= 0) return hr;
123	    const f = course.sample(s);
124	    const p = tmpV.copy(f.pos).addScaledVector(f.right, lateral);
125	    const b = WORLD.basin;
126	    const r = Math.hypot(p.x - b.center.x, p.z - b.center.z);
127	    const yW = funnelY(r) + FUNNEL_LIFT + whirlpoolHeight(p.x, p.z, t);
128	    const hw = (yW - p.y) / Math.max(0.3, f.up.y);
129	    return hr * (1 - k) + hw * k;
130	  };
131	
132	  return {
133	    group,
134	    controls,
135	    parts,
136	    surfaceHeight,
137	    stats: () => ({ instances: foam.instanceCount, bubbles: bubbles.counts.big, smallBubbles: bubbles.counts.small, sprayCapacity: spray.capacity }),
138	    update(time, dt, focusS, camera) {
139	      focus = focusS;
140	      curTime = time;
141	      ribbon.uniforms.uTime.value = time;
142	      whirl.uniforms.uTime.value = time;
143	      drum.uniforms.uTime.value = time;
144	      drum.uniforms.uAgitation.value = controls.drumAgitation;
145	      drum.swirlUniforms.uSwirl.value = controls.drumSwirl;
146	      drum.swirl.visible = controls.drumSwirl > 0.001;
147	      wave.uniforms.uTime.value = time;
148	      puddles.uniforms.uTime.value = time;
149	      puddles.uniforms.uAmount.value = controls.outro;
150	      (ribbon.uniforms.uOutro.value as THREE.Vector2).x = controls.outro;
151	      puddles.group.visible = controls.outro > 0.001;
152	      // region visibility (perf): only what the camera around focusS can see
153	      drum.group.visible = focusS < st03.s0 + 12;
154	      whirl.mesh.visible = focusS > drainMark - 8 && focusS < st04.s0 + 45;
155	      wave.mesh.visible = focusS > st08.s0 - 25;
156	      // when Benny is off the ribbon (drum / whirlpool), no ribbon wake
157	      if (focusS < ribbonS0 || whirlBlend(focusS) > 0.5) (ribbon.uniforms.uBenny.value as THREE.Vector3).z = 0;
158	      foam.update(time, focusS, controls.outro);
159	      bubbles.update(time, dt, focusS, camera, 1 - 0.7 * controls.outro);
160	      // crest spray off the final wave
161	      if (wave.mesh.visible && focusS > st09.s0 - 20 && focusS < st09.s1 + 20 && controls.outro < 0.5) {
162	        const n = quality === 'high' ? 3 : 1;
163	        for (let i = 0; i < n; i++) {
164	          const c = wave.crest[(Math.random() * wave.crest.length) | 0];
165	          if (!c) break;
166	          const f = course.sample(Math.min(course.length, Math.max(0, focusS)));
167	          tmpV2.copy(f.right).multiplyScalar(rnd(1, 3.5)).addScaledVector(f.up, rnd(1.5, 4)).addScaledVector(f.tan, rnd(-1, 2));
168	          spray.emit(c, tmpV2, rnd(0.08, 0.2), rnd(0.5, 1.0));
169	        }
170	      }
171	      spray.update(dt, camera);
172	      crown.update(time, dt);
173	      for (const k of qaHide) { const o = parts[k]; if (o) o.visible = false; }
174	    },
175	    wake(pos, forward, right, speed, dt) {
176	      // Benny's arc length / lateral from his actual position (focus lags one frame)
177	      const f0 = course.sample(Math.max(0, focus));
178	      const d = tmpV3.copy(pos).sub(f0.pos);
179	      const s = Math.min(course.length, Math.max(0, focus + d.dot(f0.tan)));
180	      const f = course.sample(s);
181	      d.copy(pos).sub(f.pos);
182	      const lateral = d.dot(f.right);
183	      // pos = Benny's real body centre (Game.ts passes it AFTER the runtime's ride lift). The waterline
184	      // radius is the chord of the fluffy ball at the water surface, so the contact foam, the crown and
185	      // the ribbon wake hug his actual footprint. (Deriving the radius from `above / BENNY_RIDE_OFFSET`
186	      // made it grow with the lift and drew a white contact band ~2x wider than the body.)
187	      const above = d.dot(f.up) - surfaceHeight(s, lateral, curTime);
188	      const waterlineR = Math.sqrt(Math.max(BENNY_OUTER_R * BENNY_OUTER_R - above * above, (0.35 * BENNY_OUTER_R) ** 2));
189	      const strength = Math.min(1, speed / 8);
190	      if (s >= ribbonS0 && whirlBlend(s) < 0.5 && !qaNoRibbonWake) {
191	        (ribbon.uniforms.uBenny.value as THREE.Vector3).set(s, lateral, strength);
192	        ribbon.uniforms.uBennyR.value = waterlineR;
193	      }
194	      // 3D V spray fans thrown back and outward from the waterline (ref 05)
195	      const center = tmpV.copy(pos).addScaledVector(f.up, -above);
196	      crown.place(center, forward, f.up, waterlineR, strength);
197	      // Benny's measured velocity: droplets inherit it so the fan stays attached to him instead of
198	      // trailing 4-6 units back toward the chase camera (the old white spots at the frame bottom).
199	      // QA checkpoints hold him still, so the measured velocity is 0 there as well.
200	      if (lastWakeT >= 0 && dt > 1e-4 && lastWake.distanceToSquared(pos) < 9) riderVel.copy(pos).sub(lastWake).divideScalar(dt);
201	      else riderVel.set(0, 0, 0);
202	      lastWake.copy(pos);
203	      lastWakeT = curTime;
204	      // droplets along the two fans: back + outward, a short hop above the surface
205	      const rate = (quality === 'high' ? 110 : 40) * strength;
206	      const n = Math.min(12, Math.floor(rate * dt + Math.random()));
207	      const up = tmpV2.copy(f.up);
208	      back.copy(forward).multiplyScalar(-1);
209	      for (let i = 0; i < n; i++) {
210	        const side = Math.random() < 0.5 ? -1 : 1;
211	        const th = rnd(0.45, 1.25); // from straight back toward sideways
212	        const cs = Math.cos(th), sn = Math.sin(th);
213	        sprP.copy(center).addScaledVector(right, side * sn * waterlineR * 1.05).addScaledVector(back, cs * waterlineR * 1.05).addScaledVector(up, rnd(0.02, 0.12));
214	        const sp = rnd(1.6, 3.6);
215	        sprV.copy(riderVel).addScaledVector(right, side * sn * sp).addScaledVector(back, cs * sp).addScaledVector(up, rnd(1.6, 3.4));
216	        spray.emit(sprP, sprV, rnd(0.035, 0.085), rnd(0.28, 0.5));
217	      }
218	    },
219	    splash(pos, up, strength) {
220	      const n = Math.round(30 * strength * (quality === 'high' ? 1 : 0.5));
221	      for (let i = 0; i < n; i++) {
222	        const dir = sprV.set(rnd(-1, 1), 0, rnd(-1, 1)).normalize().multiplyScalar(rnd(1, 4) * strength);
223	        dir.addScaledVector(up, rnd(3, 7) * strength);
224	        spray.emit(pos, dir, rnd(0.06, 0.16), rnd(0.5, 1.1));
225	      }
226	    },
227	  };
228	}
