1	/**
2	 * Rider splash fans (ref 05: two V-shaped spray fans of white/cyan streaks thrown back and outward
3	 * from Benny's base, clear water straight behind him).
4	 *
5	 * One small mesh: two polar strips (left/right fan) of angle × radial, shaped and animated in the
6	 * vertex shader, drawn with a translucent "streak + droplet" fragment shader (no lace haze). It is
7	 * placed every frame at the computed water surface under Benny's real (lifted) body centre
8	 * (index.ts `wake()`), so its root always sits on the stream at his waterline. Hidden automatically
9	 * when wake() stops being called (intro / outro).
10	 */
11	import * as THREE from 'three';
12	import { FRAG_TAIL, NOISE_GLSL, withFog } from './glsl';
13	
14	/** fan angle range from straight behind (0 = towards the chase camera, pi/2 = sideways) */
15	const TH0 = 0.32;
16	const TH1 = 1.4;
17	
18	const VERT = /* glsl */ `
19	attribute vec2 aPolar;   // x = signed angle (side * th), y = radial 0..1
20	uniform float uTime;
21	uniform float uR;        // waterline radius of Benny's body (units): fan root
22	uniform float uLen;      // fan length beyond the root (units)
23	uniform float uH;        // peak height of the spray sheet (units)
24	uniform float uStrength; // 0..1
25	varying vec2 vPolar;
26	varying vec3 vPosW;
27	#include <fog_pars_vertex>
28	float h1(float n) { return fract(sin(n) * 43758.5453); }
29	float n1(float x) { float i = floor(x); float f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(h1(i), h1(i + 1.0), f); }
30	void main() {
31	  float th = aPolar.x;
32	  float t = aPolar.y;
33	  float ath = abs(th);
34	  float wob = n1(ath * 6.0 + uTime * 6.0 + step(0.0, th) * 13.0) * 0.6 + n1(ath * 15.0 - uTime * 9.0) * 0.4;
35	  // the fan is longest on its diagonal (~45 deg back), shorter where it turns sideways
36	  float diag = 1.0 - 0.35 * smoothstep(0.9, 1.4, ath) - 0.25 * (1.0 - smoothstep(${TH0.toFixed(2)}, 0.6, ath));
37	  float r = uR * 0.92 + t * uLen * diag * (0.8 + 0.4 * wob) * (0.55 + 0.45 * uStrength);
38	  // sheet leaves the water at the body, arcs up and falls back toward the surface at its tips
39	  float y = uH * uStrength * (0.75 + 0.5 * wob) * sin(3.14159 * pow(t, 0.6)) * (1.0 - 0.45 * t) - 0.02;
40	  vec3 p = vec3(sin(th) * r, y, cos(th) * r);   // local: x = side, y = up, z = backwards
41	  vec4 wp = modelMatrix * vec4(p, 1.0);
42	  vPosW = wp.xyz;
43	  vPolar = aPolar;
44	  vec4 mvPosition = viewMatrix * wp;
45	  gl_Position = projectionMatrix * mvPosition;
46	  #include <fog_vertex>
47	}
48	`;
49	
50	const FRAG = /* glsl */ `
51	uniform float uTime;
52	uniform float uStrength;
53	varying vec2 vPolar;
54	varying vec3 vPosW;
55	#include <fog_pars_fragment>
56	${NOISE_GLSL}
57	void main() {
58	  float th = vPolar.x;
59	  float t = vPolar.y;
60	  float ath = abs(th);
61	  float seed = step(0.0, th) * 7.3;
62	  // fine radial streaks (water jets) racing outward; two scales so they never read as a solid sheet
63	  float s1 = vnoise(vec2(ath * 46.0 + seed, t * 2.2 - uTime * 5.0));
64	  float s2 = vnoise(vec2(ath * 97.0 + seed * 2.0, t * 3.5 - uTime * 7.0));
65	  float streak = max(smoothstep(0.6, 0.86, s1), smoothstep(0.66, 0.9, s2) * 0.8);
66	  // droplet beads breaking off the streak tips
67	  vec2 g = vec2(ath * 30.0 + seed, t * 9.0 - uTime * 6.0);
68	  float cd = cells(g);
69	  float beads = (1.0 - smoothstep(0.1, 0.22, cd)) * step(0.55, hash12(floor(g) + seed)) * smoothstep(0.35, 0.7, t);
70	  // fan envelope: fade at both angle limits, at the root (hidden under the fur) and toward the tips
71	  float env = smoothstep(${TH0.toFixed(2)}, ${(TH0 + 0.2).toFixed(2)}, ath) * (1.0 - smoothstep(${(TH1 - 0.3).toFixed(2)}, ${TH1.toFixed(2)}, ath));
72	  float a = (streak * (1.0 - smoothstep(0.45, 0.92, t)) + beads * (1.0 - smoothstep(0.75, 1.0, t))) * env;
73	  a *= smoothstep(0.0, 0.06, t) * uStrength;
74	  if (a < 0.03) discard;
75	  // white cores, cyan translucent edges
76	  vec3 col = mix(vec3(0.55, 0.9, 1.0), vec3(1.25, 1.28, 1.3), smoothstep(0.25, 0.8, a));
77	  gl_FragColor = vec4(col, clamp(a * 0.95, 0.0, 0.92));
78	  ${FRAG_TAIL}
79	}
80	`;
81	
82	export interface RiderSplash {
83	  mesh: THREE.Mesh;
84	  uniforms: Record<string, THREE.IUniform>;
85	  /** place on the water under Benny: waterline centre + frame + body radius at the waterline */
86	  place(center: THREE.Vector3, forward: THREE.Vector3, up: THREE.Vector3, radius: number, strength: number): void;
87	  update(time: number, dt: number): void;
88	}
89	
90	export function createRiderSplash(quality: 'high' | 'low'): RiderSplash {
91	  const S = quality === 'high' ? 22 : 12; // angular columns per fan
92	  const R = quality === 'high' ? 6 : 4;
93	  const cols = S + 1, rows = R + 1;
94	  const polar = new Float32Array(2 * cols * rows * 2);
95	  let k = 0;
96	  for (const side of [-1, 1]) {
97	    for (let i = 0; i <= S; i++) {
98	      const th = TH0 + ((TH1 - TH0) * i) / S;
99	      for (let j = 0; j <= R; j++) {
100	        polar[k++] = side * th;
101	        polar[k++] = j / R;
102	      }
103	    }
104	  }
105	  const idx: number[] = [];
106	  for (let f = 0; f < 2; f++) {
107	    const base = f * cols * rows;
108	    for (let i = 0; i < S; i++) {
109	      for (let j = 0; j < R; j++) {
110	        const a = base + i * rows + j, b = a + 1, c = a + rows, d = c + 1;
111	        idx.push(a, c, b, b, c, d);
112	      }
113	    }
114	  }
115	  const geo = new THREE.BufferGeometry();
116	  geo.setAttribute('aPolar', new THREE.BufferAttribute(polar, 2));
117	  // dummy position attribute (positions are generated in the vertex shader)
118	  geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(2 * cols * rows * 3), 3));
119	  geo.setIndex(idx);
120	  const uniforms = withFog({ uTime: { value: 0 }, uR: { value: 0.45 }, uLen: { value: 1.7 }, uH: { value: 0.32 }, uStrength: { value: 0 } });
121	  const mat = new THREE.ShaderMaterial({
122	    uniforms,
123	    vertexShader: VERT,
124	    fragmentShader: FRAG,
125	    fog: true,
126	    transparent: true,
127	    depthWrite: false,
128	    side: THREE.DoubleSide,
129	  });
130	  const mesh = new THREE.Mesh(geo, mat);
131	  mesh.name = 'rider_splash';
132	  mesh.frustumCulled = false;
133	  mesh.renderOrder = 3;
134	  mesh.visible = false;
135	  const basis = new THREE.Matrix4();
136	  const back = new THREE.Vector3();
137	  const side = new THREE.Vector3();
138	  let target = 0;
139	  let fed = false;
140	  return {
141	    mesh,
142	    uniforms,
143	    place(center, forward, up, radius, strength) {
144	      back.copy(forward).multiplyScalar(-1);
145	      side.crossVectors(up, back).normalize(); // x × y = z  →  (side, up, back) right-handed
146	      basis.makeBasis(side, up, back);
147	      mesh.quaternion.setFromRotationMatrix(basis);
148	      mesh.position.copy(center);
149	      uniforms.uR.value = radius;
150	      target = strength;
151	      fed = true;
152	    },
153	    update(time, dt) {
154	      uniforms.uTime.value = time;
155	      if (!fed) target = 0;
156	      fed = false;
157	      const s = uniforms.uStrength.value as number;
158	      const v = dt > 0 ? s + (target - s) * Math.min(1, dt * 6) : target;
159	      uniforms.uStrength.value = v;
160	      mesh.visible = v > 0.01;
161	    },
162	  };
163	}
