1	/**
2	 * Foam banks along the stream (refs 03–10) + whirlpool rim foam.
3	 *  - berm: ONE continuous lumpy lather bank per side, swept along the course (custom shader:
4	 *    two-scale cellular soap bubbles with derivative bump lighting, lavender crevices, pores,
5	 *    faint iridescent rim). This is what makes the banks read as continuous foam, not cotton balls.
6	 *  - puffs: instanced bubble puffs sitting ON the berm crest (silhouette lumps), in ~40-unit chunks
7	 *    so only chunks near Benny are drawn; quality 'low' halves density and uses 20-tri puffs.
8	 *  - foam rings on the whirlpool rim and along its spiral bands (rotating with the swirl)
9	 */
10	import * as THREE from 'three';
11	import { type Course, WORLD, funnelY } from '../world/course';
12	import { EDGE_LIFT } from './waterRibbon';
13	import { SPIRAL_C, FUNNEL_LIFT } from './whirlpool';
14	import { FRAG_FX_GLSL, FRAG_TAIL, NOISE_GLSL, withFog } from './glsl';
15	
16	/** c = (ambient occlusion 0..1, seed 0..1, tint -1..1) → instanceColor (see PUFF_VERT) */
17	interface Puff { p: THREE.Vector3; r: number; ao: number; tint: number }
18	
19	// ---------------------------------------------------------------------------------- berm profile
20	/** berm spans e ∈ [BERM_IN, BERM_OUT] units outward from the ribbon edge (negative = over the water) */
21	export const BERM_IN = -0.6;
22	export const BERM_OUT = 1.2;
23	const hash1 = (n: number) => { const x = Math.sin(n * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };
24	const noise1 = (x: number) => { const i = Math.floor(x), f = x - i, u = f * f * (3 - 2 * f); return hash1(i) * (1 - u) + hash1(i + 1) * u; };
25	/** 0..1 lumpiness of the bank at (s, side) — CPU only, baked into the mesh and the puff placement */
26	export function bermLump(s: number, side: number): number {
27	  return 0.55 * noise1(s * 0.33 + side * 31.7) + 0.45 * noise1(s * 1.05 + side * 7.3);
28	}
29	/** CPU cellular "bubble dome" field (0..1) so the bank silhouette is a pile of round lumps */
30	export function bermDomes(s: number, e: number, side: number): number {
31	  const gs = s / 0.95, ge = e / 0.62 + side * 11.3;
32	  const i0 = Math.floor(gs), j0 = Math.floor(ge);
33	  let best = 0;
34	  for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
35	    const i = i0 + di, j = j0 + dj;
36	    const ox = hash1(i * 17.13 + j * 3.71), oy = hash1(i * 5.31 + j * 19.7 + 4.2);
37	    const r = 0.45 + 0.4 * hash1(i * 7.7 + j * 13.1 + 9.9);
38	    const dx = (i + ox - gs) / r, dy = (j + oy - ge) / r;
39	    best = Math.max(best, 1 - (dx * dx + dy * dy));
40	  }
41	  return Math.max(0, best);
42	}
43	
44	/** height (along course up) of the bank surface at e units outward from the edge */
45	export function bermHeight(e: number, hw: number, lump: number): number {
46	  const uIn = Math.max(0, (hw + BERM_IN) / hw);
47	  const hIn = EDGE_LIFT * uIn * uIn * uIn - 0.07;
48	  const ep = 0.08 + 0.22 * lump;
49	  const hp = EDGE_LIFT + 0.14 + 0.5 * lump;
50	  const hOut = -0.95;
51	  if (e <= ep) {
52	    const t = Math.min(1, Math.max(0, (e - BERM_IN) / (ep - BERM_IN)));
53	    return hIn + (hp - hIn) * (1 - (1 - t) * (1 - t));
54	  }
55	  const t = Math.min(1, (e - ep) / (BERM_OUT - ep));
56	  return hp + (hOut - hp) * t * t;
57	}
58	
59	/** full bank surface height incl. bubble domes (shared by the mesh and the puff placement) */
60	export function bermSurface(s: number, e: number, side: number, hw: number): number {
61	  const domeK = Math.min(1, Math.max(0, (e + 0.3) / 0.35)) * Math.min(1, Math.max(0, (BERM_OUT - 0.1 - e) / 0.4));
62	  return bermHeight(e, hw, bermLump(s, side)) + 0.2 * domeK * Math.sqrt(bermDomes(s, e, side));
63	}
64	
65	const BERM_VERT = /* glsl */ `
66	attribute vec3 aFoam;    // x = e (units outward from the stream edge), y = s, z = side (-1 / 1)
67	uniform float uTime;
68	varying vec3 vFoam;
69	varying vec3 vPosW;
70	varying vec3 vNormalW;
71	#include <fog_pars_vertex>
72	void main() {
73	  // gentle breathing of the lather (never at the water line)
74	  float k = smoothstep(-0.2, 0.3, aFoam.x);
75	  vec3 p = position + normal * (0.03 * k * sin(uTime * 1.6 + aFoam.y * 2.1 + aFoam.z * 3.0));
76	  vec4 wp = modelMatrix * vec4(p, 1.0);
77	  vPosW = wp.xyz;
78	  vNormalW = normalize(mat3(modelMatrix) * normal);
79	  vFoam = aFoam;
80	  vec4 mvPosition = viewMatrix * wp;
81	  gl_Position = projectionMatrix * mvPosition;
82	  #include <fog_vertex>
83	}
84	`;
85	
86	const BERM_FRAG = /* glsl */ `
87	uniform float uTime;
88	uniform vec2 uOutro;     // amount, chamber start s
89	uniform vec3 uLightDir;
90	varying vec3 vFoam;
91	varying vec3 vPosW;
92	varying vec3 vNormalW;
93	#include <fog_pars_fragment>
94	${NOISE_GLSL}
95	${FRAG_FX_GLSL}
96	void main() {
97	  float s = vFoam.y;
98	  if (uOutro.x > 0.0 && s > uOutro.y - 2.0) {
99	    float n = vnoise(vec2(vFoam.x * 3.0, s * 0.35)) * 0.7 + 0.3;
100	    if (n < uOutro.x * 1.15) discard;
101	  }
102	  vec2 p = vec2(vFoam.x * vFoam.z * 1.1, s - uTime * 0.25);
103	  // detail fade with distance (cells per pixel)
104	  float fw = max(fwidth(p.x), fwidth(p.y));
105	  float k1 = 1.0 - smoothstep(0.12, 0.3, fw * 1.6);
106	  float k2 = 1.0 - smoothstep(0.12, 0.3, fw * 3.8);
107	  float c1 = mix(0.45, cells(p * 1.6), k1);
108	  #ifdef LOW_Q
109	  float c2 = c1;
110	  #else
111	  float c2 = mix(0.45, cells(p * 3.8 + 11.0), k2);
112	  #endif
113	  // bubble domes: bright cell centres, deep crevices between bubbles
114	  float bub = (1.0 - c1 * c1) * 0.6 + (1.0 - c2 * c2) * 0.4;
115	  vec3 N0 = normalize(vNormalW);
116	  if (!gl_FrontFacing) N0 = -N0;
117	  #ifdef LOW_Q
118	  vec3 N = N0;
119	  #else
120	  vec3 N = bumpNormal(vPosW, N0, bub * 0.1);
121	  #endif
122	  vec3 L = normalize(uLightDir);
123	  vec3 V = normalize(cameraPosition - vPosW);
124	  float diff = 0.55 + 0.45 * max(dot(N, L), 0.0);
125	  vec3 white = vec3(1.0, 1.0, 1.0);
126	  vec3 lav = vec3(0.7, 0.68, 0.98);
127	  vec3 col = mix(lav, white, 0.3 + 0.7 * clamp(N.y * 0.5 + 0.5, 0.0, 1.0)) * diff;
128	  col = mix(col, lav * 0.8, smoothstep(0.6, 0.95, c1) * 0.7 * k1);
129	  col = mix(col, lav * 0.9, smoothstep(0.65, 0.95, c2) * 0.4 * k2);
130	  // tiny pores (open bubbles)
131	  #ifndef LOW_Q
132	  vec2 pp = p * 7.0 + 5.0;
133	  float pc = cells(pp);
134	  float kp = 1.0 - smoothstep(0.1, 0.25, fw * 7.0);
135	  col = mix(col, vec3(0.58, 0.56, 0.88), (1.0 - smoothstep(0.1, 0.2, pc)) * step(0.62, hash12(floor(pp))) * 0.75 * kp);
136	  #endif
137	  float spec = pow(max(dot(reflect(-V, N), L), 0.0), 28.0);
138	  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 3.0);
139	  col += vec3(1.0) * spec * 0.45 + iridescent(fres * 1.4 + c1 * 0.6) * fres * 0.18;
140	  gl_FragColor = vec4(col * 0.96, 1.0);
141	  ${FRAG_TAIL}
142	}
143	`;
144	
145	// ---------------------------------------------------------------------------------- puffs
146	/**
147	 * Soap-foam puff (ref 05 "cloud banks": white-lavender clumps, #FCF6FF lit tops, soft lavender
148	 * undersides and crevices, a few darker pores, faint soap-film rim). instanceColor carries
149	 * (x = ambient occlusion 0..1, y = seed, z = tint -1..1), not a colour.
150	 */
151	const PUFF_VERT = /* glsl */ `
152	uniform float uTime;
153	varying vec3 vNormalW;
154	varying vec3 vPosW;
155	varying vec3 vLocal;
156	varying vec3 vInst;
157	#include <fog_pars_vertex>
158	void main() {
159	  vInst = instanceColor;
160	  float br = 1.0 + 0.035 * sin(uTime * 1.7 + instanceColor.y * 40.0);
161	  vec4 wp = modelMatrix * instanceMatrix * vec4(position * br, 1.0);
162	  vPosW = wp.xyz;
163	  vNormalW = normalize(mat3(modelMatrix) * mat3(instanceMatrix) * normal);
164	  vLocal = normal;
165	  vec4 mvPosition = viewMatrix * wp;
166	  gl_Position = projectionMatrix * mvPosition;
167	  #include <fog_vertex>
168	}
169	`;
170	const PUFF_FRAG = /* glsl */ `
171	uniform vec3 uLightDir;
172	varying vec3 vNormalW;
173	varying vec3 vPosW;
174	varying vec3 vLocal;
175	varying vec3 vInst;
176	#include <fog_pars_fragment>
177	${NOISE_GLSL}
178	void main() {
179	  vec3 N = normalize(vNormalW);
180	  vec3 V = normalize(cameraPosition - vPosW);
181	  vec3 L = normalize(uLightDir);
182	  float wrap = clamp(dot(N, L) * 0.55 + 0.5, 0.0, 1.0);
183	  float upF = clamp(N.y * 0.5 + 0.5, 0.0, 1.0);
184	  float lit = smoothstep(0.18, 0.88, wrap * 0.65 + upF * 0.35);
185	  vec3 lav = vec3(0.47, 0.44, 0.88);
186	  vec3 top = mix(vec3(1.1, 1.04, 1.16), vec3(1.04, 1.06, 1.16), clamp(vInst.z, 0.0, 1.0));
187	  top = mix(top, vec3(1.12, 1.02, 1.12), clamp(-vInst.z, 0.0, 1.0));
188	  vec3 col = mix(lav, top, lit);
189	  #ifndef LOW_Q
190	  // pores: small open bubbles on the puff skin (puff-local, two planar projections, no seam)
191	  vec3 an = abs(vLocal);
192	  vec2 pc = (an.x > an.z ? vLocal.zy : vLocal.xy) * 2.6 + vInst.y * 17.0;
193	  float cp = cells(pc);
194	  float kp = 1.0 - smoothstep(0.2, 0.45, fwidth(pc.x) + fwidth(pc.y));
195	  float pore = (1.0 - smoothstep(0.1, 0.2, cp)) * step(0.6, hash12(floor(pc) + vInst.y * 31.0));
196	  col = mix(col, lav * 0.95, pore * kp * 0.6 * lit);
197	  #endif
198	  // soap-film rim (cool lavender, a touch of pink) + soft glint
199	  float fres = pow(1.0 - clamp(dot(N, V), 0.0, 1.0), 2.4);
200	  col = mix(col, vec3(0.8, 0.68, 1.0), fres * 0.42);
201	  float spec = pow(max(dot(reflect(-V, N), L), 0.0), 26.0);
202	  col += vec3(1.0) * spec * 0.3;
203	  col *= mix(0.68, 1.0, vInst.x);
204	  gl_FragColor = vec4(col, 1.0);
205	  ${FRAG_TAIL}
206	}
207	`;
208	
209	function rng(seed: number) {
210	  let a = seed >>> 0;
211	  return () => {
212	    a = (a + 0x6d2b79f5) >>> 0;
213	    let t = a;
214	    t = Math.imul(t ^ (t >>> 15), t | 1);
215	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
216	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
217	  };
218	}
219	
220	function makePuffMaterial(quality: 'high' | 'low') {
221	  const uniforms = withFog({
222	    uTime: { value: 0 },
223	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
224	  });
225	  const mat = new THREE.ShaderMaterial({
226	    uniforms,
227	    vertexShader: PUFF_VERT,
228	    fragmentShader: PUFF_FRAG,
229	    fog: true,
230	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
231	  });
232	  return { mat, uniforms };
233	}
234	
235	/** unit sphere puff with smooth normals (detail 0 icosahedra get flat normals by default) */
236	function puffGeometry(detail: number) {
237	  const g = new THREE.IcosahedronGeometry(1, detail);
238	  const p = g.attributes.position as THREE.BufferAttribute;
239	  const n = g.attributes.normal as THREE.BufferAttribute;
240	  const v = new THREE.Vector3();
241	  for (let i = 0; i < p.count; i++) { v.fromBufferAttribute(p, i).normalize(); n.setXYZ(i, v.x, v.y, v.z); }
242	  return g;
243	}
244	
245	export interface FoamSystem {
246	  group: THREE.Group;
247	  whirlGroup: THREE.Group;
248	  berm: THREE.Mesh;
249	  update(time: number, focusS: number, outro?: number): void;
250	  instanceCount: number;
251	}
252	
253	/** continuous lather bank along both stream edges (skips the 03 whirlpool interior) */
254	function createBerm(course: Course, s0: number, s1: number, skip: [number, number], quality: 'high' | 'low') {
255	  const ds = quality === 'high' ? 0.32 : 0.8;
256	  const E = quality === 'high' ? [BERM_IN, -0.4, -0.25, -0.1, 0.04, 0.18, 0.34, 0.52, 0.75, 0.98, BERM_OUT] : [BERM_IN, -0.2, 0.15, 0.55, BERM_OUT];
257	  const rows = Math.ceil((s1 - s0) / ds) + 1;
258	  const C = E.length;
259	  const n = rows * C * 2;
260	  const pos = new Float32Array(n * 3);
261	  const foam = new Float32Array(n * 3);
262	  const tmp = new THREE.Vector3();
263	  let k = 0;
264	  const rowS: number[] = [];
265	  for (let i = 0; i < rows; i++) {
266	    const s = Math.min(s1, s0 + i * ds);
267	    rowS.push(s);
268	    const f = course.sample(s);
269	    const hw = course.widthAt(s) / 2;
270	    for (const side of [-1, 1]) {
271	      for (let j = 0; j < C; j++) {
272	        // left side is mirrored so every row runs inner → outer; bubble domes everywhere except
273	        // at the water line (keeps the lace edge flush with the stream)
274	        const e = E[j];
275	        const h = bermSurface(s, e, side, hw);
276	        tmp.copy(f.pos).addScaledVector(f.right, side * (hw + e)).addScaledVector(f.up, h);
277	        tmp.toArray(pos, k * 3);
278	        foam[k * 3] = e;
279	        foam[k * 3 + 1] = s;
280	        foam[k * 3 + 2] = side;
281	        k++;
282	      }
283	    }
284	  }
285	  const idx: number[] = [];
286	  const rowStride = C * 2;
287	  for (let i = 0; i < rows - 1; i++) {
288	    const sa = rowS[i], sb = rowS[i + 1];
289	    if (sb > skip[0] && sa < skip[1]) continue;
290	    for (let sideI = 0; sideI < 2; sideI++) {
291	      for (let j = 0; j < C - 1; j++) {
292	        const a = i * rowStride + sideI * C + j, b = a + 1, c = a + rowStride, d = c + 1;
293	        // CCW seen from above on both sides (side +1 runs +right, side −1 runs −right)
294	        if (sideI === 1) idx.push(a, b, c, b, d, c);
295	        else idx.push(a, c, b, b, c, d);
296	      }
297	    }
298	  }
299	  const geo = new THREE.BufferGeometry();
300	  geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
301	  geo.setAttribute('aFoam', new THREE.BufferAttribute(foam, 3));
302	  geo.setIndex(idx);
303	  geo.computeVertexNormals();
304	  const uniforms = withFog({
305	    uTime: { value: 0 },
306	    uOutro: { value: new THREE.Vector2(0, course.stage('08').s0) },
307	    uLightDir: { value: new THREE.Vector3(0.3, 1.0, 0.45).normalize() },
308	  });
309	  const mat = new THREE.ShaderMaterial({
310	    uniforms,
311	    vertexShader: BERM_VERT,
312	    fragmentShader: BERM_FRAG,
313	    fog: true,
314	    side: THREE.DoubleSide,
315	    defines: quality === 'low' ? { LOW_Q: 1 } : {},
316	  });
317	  const mesh = new THREE.Mesh(geo, mat);
318	  mesh.name = 'foam_berm';
319	  mesh.frustumCulled = false;
320	  return { mesh, uniforms };
321	}
322	
323	export function createFoam(course: Course, opts: { s0: number; s1: number; quality: 'high' | 'low' }): FoamSystem {
324	  const { s0, s1, quality } = opts;
325	  const rand = rng(1337);
326	  const density = quality === 'high' ? 1 : 0.5;
327	  // LOD: 80-tri puffs in the chunks around Benny, 20-tri puffs further out (low tier: 20-tri only)
328	  const geoHi = puffGeometry(quality === 'high' ? 1 : 0);
329	  const geoLo = quality === 'high' ? puffGeometry(0) : geoHi;
330	  const puff = makePuffMaterial(quality);
331	  const mat = puff.mat;
332	  const group = new THREE.Group();
333	  group.name = 'foam_banks';
334	  const st03 = course.stage('03'), st04 = course.stage('04');
335	  const chunkLen = 24;
336	  const chunks: { mesh: THREE.InstancedMesh; sa: number; sb: number }[] = [];
337	  let total = 0;
338	  const tmpM = new THREE.Matrix4();
339	  const tmpQ = new THREE.Quaternion();
340	  const tmpS = new THREE.Vector3();
341	  const tmpE = new THREE.Euler();
342	  const tmpC = new THREE.Color();
343	
344	  const build = (list: Puff[], parent: THREE.Object3D, sa: number, sb: number) => {
345	    if (!list.length) return;
346	    const mesh = new THREE.InstancedMesh(geoHi, mat, list.length);
347	    list.forEach((pf, i) => {
348	      tmpQ.setFromEuler(tmpE.set(rand() * 6, rand() * 6, rand() * 6));
349	      tmpS.set(pf.r, pf.r * (0.78 + rand() * 0.22), pf.r);
350	      tmpM.compose(pf.p, tmpQ, tmpS);
351	      mesh.setMatrixAt(i, tmpM);
352	      mesh.setColorAt(i, tmpC.setRGB(pf.ao, rand(), pf.tint));
353	    });
354	    mesh.instanceMatrix.needsUpdate = true;
355	    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
356	    mesh.computeBoundingSphere();
357	    parent.add(mesh);
358	    chunks.push({ mesh, sa, sb });
359	    total += list.length;
360	  };
361	
362	  // ---- continuous lather bank (berm) along both edges ----
363	  const skip: [number, number] = [st03.s0 + 4, st04.s0 - 6];
364	  const berm = createBerm(course, s0, s1, skip, quality);
365	  group.add(berm.mesh);
366	
367	  // ---- cloud banks of puffs hugging both stream edges (ref 05: 10–40 px white-lavender clumps) ----
368	  const inSkip = (s: number) => s > skip[0] && s < skip[1];
369	  const addPuff = (list: Puff[], s: number, e: number, side: number, r: number, lift: number, ao: number) => {
370	    const ss = Math.min(s1, Math.max(s0, s));
371	    if (inSkip(ss)) return;
372	    const f = course.sample(ss);
373	    const hw = course.widthAt(ss) / 2;
374	    const h = bermSurface(ss, e, side, hw) + lift;
375	    const p = f.pos.clone().addScaledVector(f.right, side * (hw + e)).addScaledVector(f.up, h);
376	    list.push({ p, r, ao, tint: rand() * 2 - 1 });
377	  };
378	  const step = quality === 'high' ? 0.36 : 0.62;
379	  for (let sa = s0; sa < s1; sa += chunkLen) {
380	    const sb = Math.min(s1, sa + chunkLen);
381	    const list: Puff[] = [];
382	    // skip most of 03 (the whirlpool has its own foam), keep the chute→rim hand-over
383	    for (let s = sa; s < sb; s += step) {
384	      if (inSkip(s)) continue;
385	      for (const side of [-1, 1]) {
386	        // crest puffs: the body of the bank
387	        const nC = quality === 'high' && rand() < 0.55 ? 2 : 1;
388	        for (let k = 0; k < nC; k++) {
389	          const r = 0.11 + rand() * 0.13;
390	          addPuff(list, s + (rand() - 0.5) * step, -0.32 + rand() * 0.82, side, r, r * (0.05 + rand() * 0.3), 0.8 + 0.2 * rand());
391	        }
392	        // small puffs right at the water line (the lacy edge of the bank)
393	        if (rand() < 0.65) {
394	          const r = 0.06 + rand() * 0.06;
395	          addPuff(list, s + (rand() - 0.5) * step, -0.58 + rand() * 0.28, side, r, r * 0.15, 0.9);
396	        }
397	      }
398	      // heaps: clusters of big puffs stacked on the crest → lumpy cloud-bank silhouette
399	      if (rand() < (quality === 'high' ? 0.16 : 0.1)) {
400	        const side = rand() < 0.5 ? -1 : 1;
401	        const n = 5 + ((rand() * 6) | 0);
402	        const ec = -0.1 + rand() * 0.55;
403	        for (let k = 0; k < n; k++) {
404	          const r = 0.15 + rand() * 0.18;
405	          const stack = k > 2 && rand() < 0.4 ? r * 0.65 : 0;
406	          const lift = r * (0.1 + rand() * 0.45) + stack;
407	          addPuff(list, s + (rand() - 0.5) * 1.8, ec + (rand() - 0.5) * 0.55, side, r, lift, 0.72 + 0.28 * Math.min(1, lift / (r * 0.9)));
408	        }
409	      }
410	    }
411	    build(list, group, sa - 2, sb + 2);
412	  }
413	
414	  // ---- whirlpool: rim ring + spiral band foam (rotates with the swirl) ----
415	  const whirlGroup = new THREE.Group();
416	  whirlGroup.name = 'foam_whirlpool';
417	  const b = WORLD.basin;
418	  whirlGroup.position.set(b.center.x, 0, b.center.z);
419	  const wl: Puff[] = [];
420	  // rim: cloud clusters of soap foam with a thin continuous fringe between them
421	  const nClusters = Math.round(26 * density);
422	  for (let k = 0; k < nClusters; k++) {
423	    const th0 = rand() * Math.PI * 2;
424	    const n = 10 + ((rand() * 16) | 0);
425	    for (let i = 0; i < n; i++) {
426	      const th = th0 + (rand() - 0.5) * 0.35;
427	      const r = b.rimRadius - 0.7 + (rand() - 0.4) * 1.3;
428	      const sz = 0.18 + rand() * 0.42;
429	      wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.35 + rand() * 0.55, r * Math.cos(th)), r: sz, ao: 0.75 + 0.25 * rand(), tint: rand() * 2 - 1 });
430	    }
431	  }
432	  const nRim = Math.round(200 * density);
433	  for (let i = 0; i < nRim; i++) {
434	    const th = rand() * Math.PI * 2;
435	    const r = b.rimRadius - 0.4 + (rand() - 0.5) * 0.6;
436	    const sz = 0.1 + rand() * 0.18;
437	    wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.3, r * Math.cos(th)), r: sz, ao: 0.85 + 0.15 * rand(), tint: rand() * 2 - 1 });
438	  }
439	  // along 3 spiral flow lines (constant th - C ln r) to echo the white foam bands
440	  const nBand = Math.round(60 * density);
441	  for (let i = 0; i < nBand; i++) {
442	    const band = ((i % 3) * Math.PI * 2) / 3 + 0.4;
443	    const r = 3.0 + rand() * (b.rimRadius - 3.6);
444	    const th = band + SPIRAL_C * Math.log(r) + (rand() - 0.5) * 0.12;
445	    const sz = 0.07 + rand() * 0.13;
446	    wl.push({ p: new THREE.Vector3(r * Math.sin(th), funnelY(r) + FUNNEL_LIFT + sz * 0.3, r * Math.cos(th)), r: sz, ao: 0.85 + 0.15 * rand(), tint: rand() * 2 - 1 });
447	  }
448	  const whirlStart = chunks.length;
449	  build(wl, whirlGroup, st03.s0 - 30, st04.s0 + 25);
450	  group.add(whirlGroup);
451	
452	  return {
453	    group,
454	    whirlGroup,
455	    berm: berm.mesh,
456	    instanceCount: total,
457	    update(time, focusS, outro = 0) {
458	      berm.uniforms.uTime.value = time;
459	      (berm.uniforms.uOutro.value as THREE.Vector2).x = outro;
460	      const s08 = course.stage('08').s0;
461	      puff.uniforms.uTime.value = time;
462	      for (let i = 0; i < chunks.length; i++) {
463	        const c = chunks[i];
464	        c.mesh.visible = c.sb > focusS - 12 && c.sa < focusS + 130 && !(outro > 0.3 && c.sb > s08 + 8);
465	        if (c.mesh.visible) c.mesh.geometry = c.sb > focusS - 12 && c.sa < focusS + 30 ? geoHi : geoLo;
466	      }
467	      // rotate whirlpool foam about the basin axis with the swirl (θ decreasing = course direction)
468	      whirlGroup.rotation.y = -time * 0.45 * ((Math.PI * 2) / 3);
469	      void whirlStart;
470	    },
471	  };
472	}
