1	/**
2	 * Iridescent soap bubbles.
3	 *  - big bubbles: instanced camera-facing sphere IMPOSTORS (2 triangles each) with an analytic
4	 *    thin-film shader: saturated magenta/cyan film, crisp outline, tinted interior, white window
5	 *    highlights (ref 05). The on-screen diameter is capped (uMaxPx) and bubbles fade out close to the
6	 *    camera, so a bubble can never become a giant occluding sphere.
7	 *  - small bubbles: one THREE.Points draw of tiny ring-sprite bubbles.
8	 * Ride (03–10): bubbles live only at the SIDES of the stream, over the foam banks and the lower
9	 * walls (ref 05: ≈18 large 25–65 px + ≈25 small, none over the path or Benny). Drum A (01–02):
10	 * free-floating in the drum volume as before.
11	 * Pooled (fixed arrays, no per-frame allocation); respawned ahead when Benny passes them.
12	 */
13	import * as THREE from 'three';
14	import { type Course, WORLD } from '../world/course';
15	import { BERM_OUT } from './foam';
16	import { FRAG_TAIL, NOISE_GLSL, withFog } from './glsl';
17	
18	const BIG_VERT = /* glsl */ `
19	attribute float aSeed;
20	uniform float uFocal;   // pixels per unit at depth 1 (viewport height / (2 tan(fov/2)))
21	uniform float uMaxPx;   // cap on the on-screen diameter
22	uniform float uNear;    // fade-out distance from the camera
23	varying vec2 vP;
24	varying float vSeed;
25	varying float vFade;
26	varying float vPx;
27	#include <fog_pars_vertex>
28	void main() {
29	  vec4 c = modelMatrix * instanceMatrix * vec4(0.0, 0.0, 0.0, 1.0);
30	  float r = length((instanceMatrix * vec4(1.0, 0.0, 0.0, 0.0)).xyz);
31	  vec4 cv = viewMatrix * c;
32	  float depth = max(-cv.z, 0.01);
33	  float px = 2.0 * r * uFocal / depth;
34	  float k = min(1.0, uMaxPx / max(px, 1e-3));
35	  r *= k;
36	  vPx = px * k;
37	  vFade = smoothstep(uNear, uNear * 1.8, depth) * step(0.0005, r);
38	  vP = position.xy;
39	  vSeed = aSeed;
40	  vec4 mvPosition = cv + vec4(position.xy * r, 0.0, 0.0);
41	  gl_Position = projectionMatrix * mvPosition;
42	  #include <fog_vertex>
43	}
44	`;
45	const BIG_FRAG = /* glsl */ `
46	uniform float uTime;
47	varying vec2 vP;
48	varying float vSeed;
49	varying float vFade;
50	varying float vPx;
51	#include <fog_pars_fragment>
52	${NOISE_GLSL}
53	void main() {
54	  float d2 = dot(vP, vP);
55	  if (d2 > 1.0 || vFade < 0.01) discard;
56	  float d = sqrt(d2);
57	  float z = sqrt(1.0 - d2);
58	  float f = 1.0 - z;                                   // 0 centre → 1 silhouette
59	  // swirling thin film: magenta / violet / cyan bands with a little gold (ref 05)
60	  float sw = vnoise(vP * 2.2 + vec2(uTime * 0.3 + vSeed * 13.0, vSeed * 7.0));
61	  float hue = f * 0.85 + sw * 0.75 + vP.x * 0.25 - vP.y * 0.2 + vSeed;
62	  vec3 film = iridescent(hue);
63	  film = vec3(film.r, film.g * 0.55 + 0.1, min(1.0, film.b * 1.1 + 0.1));   // less green
64	  film *= 0.74;                                        // stay under the tone-mapping knee: saturated
65	  float rim = smoothstep(0.5, 0.97, d);
66	  float edge = smoothstep(0.88, 0.97, d) * (1.0 - smoothstep(0.975, 1.0, d));
67	  // window highlights: a soft bright pane up-left, a small one down-right, sparkle dots on the rim
68	  vec2 q1 = (vP - vec2(-0.36, 0.42)) * vec2(2.2, 3.0);
69	  float hl = exp(-dot(q1, q1) * 2.2) * 1.2;
70	  vec2 q2 = vP - vec2(0.42, -0.45);
71	  hl += exp(-dot(q2, q2) * 55.0) * 0.7;
72	  float ang = atan(vP.y, vP.x);
73	  hl += smoothstep(0.8, 0.93, d) * (1.0 - smoothstep(0.95, 1.0, d)) * pow(max(0.0, sin(ang * 4.0 + vSeed * 31.0)), 30.0) * 0.9;
74	  // tiny bubbles: keep only the ring + one glint (no shimmering detail below ~14 px)
75	  float small = 1.0 - smoothstep(10.0, 22.0, vPx);
76	  hl *= 1.0 - 0.5 * small;
77	  vec3 col = film * (0.55 + 0.75 * rim) + vec3(1.0) * edge * 0.45 + vec3(1.05) * hl;
78	  float a = 0.14 + 0.1 * sw + rim * 0.6 + edge * 0.35 + hl;
79	  gl_FragColor = vec4(col, clamp(a, 0.0, 0.95) * vFade);
80	  ${FRAG_TAIL}
81	}
82	`;
83	
84	const PT_VERT = /* glsl */ `
85	attribute float aSize;
86	attribute float aSeed;
87	uniform float uScale;
88	uniform float uMaxPx;
89	varying float vSeed;
90	varying float vPx;
91	#include <fog_pars_vertex>
92	void main() {
93	  vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
94	  float px = aSize * uScale / max(-mvPosition.z, 0.01);
95	  gl_PointSize = aSize > 0.0 ? clamp(px, 2.0, uMaxPx) : 0.0;
96	  vPx = gl_PointSize;
97	  vSeed = aSeed;
98	  gl_Position = projectionMatrix * mvPosition;
99	  #include <fog_vertex>
100	}
101	`;
102	const PT_FRAG = /* glsl */ `
103	uniform float uTime;
104	varying float vSeed;
105	varying float vPx;
106	#include <fog_pars_fragment>
107	${NOISE_GLSL}
108	void main() {
109	  vec2 c = gl_PointCoord - 0.5;
110	  float d = length(c) * 2.0;
111	  if (d > 1.0) discard;
112	  float ring = smoothstep(0.5, 0.85, d) * (1.0 - smoothstep(0.9, 1.0, d));
113	  vec3 irid = iridescent(d * 0.7 + vSeed + atan(c.y, c.x) * 0.12);
114	  irid = vec3(irid.r, irid.g * 0.55 + 0.1, irid.b) * 0.8;
115	  float hl = smoothstep(0.26, 0.0, length(c - vec2(-0.17, -0.17)));
116	  vec3 col = mix(vec3(1.0), irid, 0.6) * ring * 1.2 + vec3(1.0) * hl * 1.4 + irid * 0.25;
117	  // tiny sprites must not read as solid white dots: keep rim + glint, fade the very smallest
118	  float alpha = clamp(ring * 0.8 + hl + 0.12, 0.0, 1.0) * (0.35 + 0.65 * smoothstep(3.0, 8.0, vPx));
119	  gl_FragColor = vec4(col, alpha);
120	  ${FRAG_TAIL}
121	}
122	`;
123	
124	interface BubbleState {
125	  s: number;
126	  pos: THREE.Vector3;
127	  vel: THREE.Vector3;
128	  size: number;
129	  phase: number;
130	  age: number;
131	  life: number;
132	}
133	
134	export interface BubbleSystem {
135	  group: THREE.Group;
136	  big: THREE.InstancedMesh;
137	  small: THREE.Points;
138	  update(time: number, dt: number, focusS: number, camera: THREE.Camera, density?: number): void;
139	  counts: { big: number; small: number };
140	}
141	
142	function rnd(a: number, b: number) {
143	  return a + Math.random() * (b - a);
144	}
145	
146	/** ride counts (visible at once in a 05-like frame) and caps, per quality tier */
147	const RIDE = {
148	  high: { big: 26, small: 36 },
149	  low: { big: 16, small: 20 },
150	};
151	/** max on-screen diameters (px at the capture/device resolution) */
152	const MAX_PX_RIDE = 66;
153	const MAX_PX_DRUM = 120;
154	const MAX_PX_SMALL = 22;
155	
156	export function createBubbles(course: Course, opts: { quality: 'high' | 'low'; sStart: number }): BubbleSystem {
157	  const quality = opts.quality;
158	  const ride = RIDE[quality];
159	  const nBig = Math.max(ride.big, 16);
160	  const nSmall = quality === 'high' ? 170 : 80; // drum A keeps its fizz; the ride uses ride.small
161	  const group = new THREE.Group();
162	  group.name = 'bubbles';
163	  const dA = WORLD.drumA;
164	  const drumEnd = course.marks['02_drain'] ?? course.stage('03').s0;
165	
166	  // ---- big (impostors) ----
167	  const quad = new THREE.PlaneGeometry(2, 2);
168	  const seeds = new Float32Array(nBig).map(() => Math.random());
169	  quad.setAttribute('aSeed', new THREE.InstancedBufferAttribute(seeds, 1));
170	  const bigUniforms = withFog({ uTime: { value: 0 }, uFocal: { value: 1000 }, uMaxPx: { value: MAX_PX_RIDE }, uNear: { value: 3.2 } });
171	  const big = new THREE.InstancedMesh(
172	    quad,
173	    new THREE.ShaderMaterial({ uniforms: bigUniforms, vertexShader: BIG_VERT, fragmentShader: BIG_FRAG, fog: true, transparent: true, depthWrite: false }),
174	    nBig,
175	  );
176	  big.name = 'bubbles_big';
177	  big.frustumCulled = false;
178	  big.renderOrder = 5;
179	  group.add(big);
180	
181	  // ---- small ----
182	  const sPos = new Float32Array(nSmall * 3);
183	  const sSize = new Float32Array(nSmall);
184	  const sSeed = new Float32Array(nSmall).map(() => Math.random());
185	  const pGeo = new THREE.BufferGeometry();
186	  pGeo.setAttribute('position', new THREE.BufferAttribute(sPos, 3).setUsage(THREE.DynamicDrawUsage));
187	  pGeo.setAttribute('aSize', new THREE.BufferAttribute(sSize, 1).setUsage(THREE.DynamicDrawUsage));
188	  pGeo.setAttribute('aSeed', new THREE.BufferAttribute(sSeed, 1));
189	  const ptUniforms = withFog({ uTime: { value: 0 }, uScale: { value: 600 }, uMaxPx: { value: MAX_PX_SMALL } });
190	  const small = new THREE.Points(
191	    pGeo,
192	    new THREE.ShaderMaterial({ uniforms: ptUniforms, vertexShader: PT_VERT, fragmentShader: PT_FRAG, fog: true, transparent: true, depthWrite: false }),
193	  );
194	  small.name = 'bubbles_small';
195	  small.frustumCulled = false;
196	  small.renderOrder = 4;
197	  group.add(small);
198	
199	  const mk = (): BubbleState => ({ s: 0, pos: new THREE.Vector3(), vel: new THREE.Vector3(), size: 1, phase: 0, age: 0, life: 1 });
200	  const bigS: BubbleState[] = Array.from({ length: nBig }, mk);
201	  const smallS: BubbleState[] = Array.from({ length: nSmall }, mk);
202	
203	  const tmp = new THREE.Vector3();
204	  const tmp2 = new THREE.Vector3();
205	  const tmp3 = new THREE.Vector3();
206	  /** camera basis of the current frame (screen-space placement / exclusion) */
207	  const view = { pos: new THREE.Vector3(), dir: new THREE.Vector3(0, 0, -1), right: new THREE.Vector3(1, 0, 0), tanV: 0.6, tanH: 0.34, inv: new THREE.Matrix4(), ok: false };
208	  /**
209	   * 1 = fine, 0 = in the no-bubble corridor (stream centre: Benny, splash, coin line), -1 = out of
210	   * the frame / too close to the camera. NDC from the camera basis.
211	   */
212	  const allowed = (p: THREE.Vector3): number => {
213	    if (!view.ok) return 1;
214	    const v = tmp3.copy(p).applyMatrix4(view.inv);
215	    const depth = -v.z;
216	    if (depth < 2.5) return -1;
217	    const xn = v.x / (depth * view.tanH), yn = v.y / (depth * view.tanV);
218	    if (Math.abs(xn) > 1.12 || yn < -1.12 || yn > 1.1) return -1;
219	    if (yn > 0.62) return 0; // upper tube / HUD: keep clear (ref 05 has none there)
220	    const corridor = yn < 0.1 ? 0.46 : 0.3;
221	    return Math.abs(xn) < corridor ? 0 : 1;
222	  };
223	  const spawn = (b: BubbleState, focusS: number, isBig: boolean, initial: boolean) => {
224	    b.phase = Math.random() * 6.28;
225	    b.age = initial ? rnd(0.5, 3) : 0;
226	    b.life = rnd(7, 15);
227	    if (focusS < drumEnd) {
228	      // Drum A volume: big bubbles floating around the drum, small ones near the water
229	      const th = rnd(0, Math.PI * 2);
230	      const r = Math.sqrt(Math.random()) * (dA.radius - 0.9);
231	      const x = dA.center.x + Math.cos(th) * r;
232	      const y = isBig ? rnd(dA.waterY - 0.2, dA.center.y + dA.radius * 0.7) : rnd(dA.waterY + 0.05, dA.waterY + 1.6);
233	      const z = rnd(dA.zBack + 0.6, dA.zDoor - 0.4);
234	      b.pos.set(x, y, z);
235	      b.s = focusS;
236	      b.vel.set(rnd(-0.15, 0.15), rnd(0.05, 0.25), rnd(-0.1, 0.1));
237	      b.size = isBig ? (Math.random() < 0.25 ? rnd(0.45, 0.85) : rnd(0.16, 0.42)) : rnd(0.05, 0.16);
238	      return;
239	    }
240	    // ---- ride: at the SIDES of the frame only (over the foam banks / outer water), never over the
241	    // stream corridor where Benny, his splash and the coin line are (ref 05). Placement is done in
242	    // screen space so it holds for any camera / stream width: pick a depth and a side screen x, find
243	    // that view ray's course position, then sit the bubble just above the water or the bank.
244	    let D: number;
245	    if (initial) D = isBig ? 6 + 40 * Math.pow(Math.random(), 1.4) : 5 + 32 * Math.pow(Math.random(), 1.2);
246	    else D = Math.random() < 0.45 ? rnd(7, 18) : rnd(18, isBig ? 46 : 38);
247	    const side = Math.random() < 0.5 ? -1 : 1;
248	    for (let attempt = 0; attempt < 4; attempt++) {
249	      const xn = side * rnd(0.52, 0.95);
250	      tmp.copy(view.pos).addScaledVector(view.dir, D).addScaledVector(view.right, xn * D * view.tanH);
251	      // course coordinates of that point (two Newton steps on the arc length)
252	      let s = focusS;
253	      for (let it = 0; it < 2; it++) {
254	        const fi = course.sample(Math.min(course.length, Math.max(opts.sStart, s)));
255	        s += tmp2.copy(tmp).sub(fi.pos).dot(fi.tan);
256	      }
257	      s = Math.min(course.length - 0.3, Math.max(opts.sStart, s));
258	      const f = course.sample(s);
259	      const hw = course.widthAt(s) / 2;
260	      let lat = tmp2.copy(tmp).sub(f.pos).dot(f.right);
261	      lat = THREE.MathUtils.clamp(lat, -(hw + BERM_OUT + 0.4), hw + BERM_OUT + 0.4);
262	      const onBank = Math.abs(lat) > hw - 0.5;
263	      const h = (isBig ? (Math.random() < 0.8 ? rnd(0.35, 1.7) : rnd(1.7, 2.8)) : rnd(0.2, 1.2)) + (onBank ? 0.45 : 0.05);
264	      b.pos.copy(f.pos).addScaledVector(f.right, lat).addScaledVector(f.up, h);
265	      b.s = s;
266	      const flow = course.prop(s, 'speed') * (isBig ? 0.1 : 0.2);
267	      b.vel.copy(f.tan).multiplyScalar(flow).addScaledVector(f.up, rnd(0.04, 0.2));
268	      if (allowed(b.pos) > 0) break;
269	    }
270	    if (isBig) b.size = Math.random() < 0.3 ? rnd(0.26, 0.36) : rnd(0.12, 0.26); // ≈25–65 px over 8–30 units
271	    else b.size = rnd(0.06, 0.16); // point-sprite diameter
272	  };
273	
274	  let lastFocus = -1e9;
275	  const tmpM = new THREE.Matrix4();
276	  const one = new THREE.Quaternion();
277	  const scl = new THREE.Vector3();
278	
279	  return {
280	    group,
281	    big,
282	    small,
283	    counts: { big: nBig, small: nSmall },
284	    update(time, dt, focusS, camera, density = 1) {
285	      bigUniforms.uTime.value = time;
286	      ptUniforms.uTime.value = time;
287	      const persp = camera as THREE.PerspectiveCamera;
288	      view.ok = !!persp.isPerspectiveCamera;
289	      if (view.ok) {
290	        camera.updateMatrixWorld();
291	        view.inv.copy(camera.matrixWorldInverse);
292	        camera.getWorldPosition(view.pos);
293	        camera.getWorldDirection(view.dir);
294	        view.right.setFromMatrixColumn(camera.matrixWorld, 0).normalize();
295	        view.tanV = Math.tan(THREE.MathUtils.degToRad(persp.fov) / 2);
296	        view.tanH = view.tanV * persp.aspect;
