#!/usr/bin/env node
// Scratch: capture one checkpoint with several query-string variants using ONE vite + ONE browser.
//   node multi.mjs <id> <outDir> <name1>=<query1> <name2>=<query2> ...   (query may be empty: base=)
// Must be run with cwd = project root.
import { mkdirSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';

const root = process.cwd();
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(resolve(root, 'scripts/lib/pw.mjs')).href);
const [id, outDir, ...variants] = process.argv.slice(2);
mkdirSync(outDir, { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(5231);
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const log = [];
try {
  for (const v of variants) {
    const eq = v.indexOf('=');
    const name = v.slice(0, eq);
    const q = v.slice(eq + 1);
    const [w, h] = id === '03' ? [727, 1536] : [864, 1536];
    const page = await browser.newPage({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
    const errs = [];
    page.on('pageerror', (e) => errs.push(e.message));
    page.on('console', (m) => { if (m.type() === 'error') errs.push(m.text()); });
    const t0 = Date.now();
    await page.goto(`${vite.url}/?qa=1&dpr=1${q ? '&' + q : ''}`);
    await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
    const err = await page.evaluate(() => window.__error);
    if (err) throw new Error(err);
    await page.evaluate((cid) => window.__rainbow.goto(cid), id);
    await page.evaluate(() => new Promise((r) => requestAnimationFrame(() => r())));
    await page.evaluate(() => document.fonts.ready);
    await page.waitForTimeout(250);
    const file = `${outDir}/${id}_${name}.png`;
    await page.screenshot({ path: file, timeout: 180000 });
    const stats = await page.evaluate(() => window.__rainbow.stats());
    const state = await page.evaluate(() => window.__rainbow.state());
    const bs = await page.evaluate(() => window.__rainbow.bennyScreen());
    log.push({ name, q, file, secs: (Date.now() - t0) / 1000, stats: { calls: stats.calls, tris: stats.triangles }, state, bennyScreen: bs, errs: errs.slice(0, 5) });
    console.log(name, '→', file, JSON.stringify({ calls: stats.calls, tris: stats.triangles, s: state.s, secs: (Date.now() - t0) / 1000, errs: errs.length }));
    await page.close();
  }
} finally {
  writeFileSync(`${outDir}/multi_log.json`, JSON.stringify(log, null, 2));
  await browser.close();
  await vite.close();
}

