#!/usr/bin/env node
// Scratch: raycast a screen grid on checkpoint 05 and map hits to course (s, lateral, edge distance).
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { writeFileSync } from 'node:fs';
const root = process.cwd();
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(resolve(root, 'scripts/lib/pw.mjs')).href);
const id = process.argv[2] ?? '05';
const q = process.argv[3] ?? '';
const { chromium } = loadPlaywright();
const vite = await startVite(5241);
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  await page.goto(`${vite.url}/?qa=1&dpr=1${q ? '&' + q : ''}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
  await page.evaluate((cid) => window.__rainbow.goto(cid), id);
  const res = await page.evaluate(() => {
    const R = window.__rainbow;
    const c = R.course;
    const st = R.state();
    const out = { state: st, benny: R.bennyScreen(), grid: [] };
    const toCourse = (p) => {
      let s = st.s;
      for (let it = 0; it < 4; it++) {
        const f = c.sample(Math.min(c.length, Math.max(0, s)));
        s += (p[0] - f.pos.x) * f.tan.x + (p[1] - f.pos.y) * f.tan.y + (p[2] - f.pos.z) * f.tan.z;
      }
      const f = c.sample(s);
      const lat = (p[0] - f.pos.x) * f.right.x + (p[1] - f.pos.y) * f.right.y + (p[2] - f.pos.z) * f.right.z;
      const up = (p[0] - f.pos.x) * f.up.x + (p[1] - f.pos.y) * f.up.y + (p[2] - f.pos.z) * f.up.z;
      const hw = c.widthAt(s) / 2;
      return { s: +s.toFixed(2), lat: +lat.toFixed(2), up: +up.toFixed(2), hw: +hw.toFixed(2), e: +(Math.abs(lat) - hw).toFixed(2) };
    };
    for (let py = 500; py <= 1500; py += 50) {
      for (let px = 0; px <= 864; px += 48) {
        const x = (px / 864) * 2 - 1, y = 1 - (py / 1536) * 2;
        const h = R.probe(x, y);
        const first = h[0];
        out.grid.push({ px, py, obj: first ? first.obj.split('<')[0] : null, d: first?.d, cc: first ? toCourse(first.p) : null });
      }
    }
    return out;
  });
  writeFileSync(process.argv[4] ?? 'probe.json', JSON.stringify(res, null, 1));
  console.log(JSON.stringify(res.state), JSON.stringify(res.benny));
} finally {
  await browser.close();
  await vite.close();
}

